-- Server settings (servers/daddyrp/daddy_college/locales/tr.lua)
-- DaddyRP: the canteen and the janitor are one job here, Kantin ve Temizlik ('kantin'), so both roles carry its name.
do
    local dc, kit = Locales.tr.tablet.dc, Locales.tr.testkit or {}
    for _, key in ipairs({ 'dr_role_canteen', 'dr_role_janitor', 'dr_roles_canteen', 'dr_roles_janitor' }) do dc[key] = 'Kantin ve Temizlik' end
    kit.role_janitor, kit.role_canteen = 'Kantin ve Temizlik', 'Kantin ve Temizlik'
    kit.role_janitor_hint = 'Mesleğin Kantin ve Temizlik olur: kantin kasası ve hademe iş emirleri'
    kit.role_canteen_hint = kit.role_janitor_hint
    kit.janitor_warn_role = "Uyarı: mesleğin Kantin ve Temizlik değil, iş emri sana gelmez: Rolüm > Kantin ve Temizlik."
end
